// ============================================
// CONFIGURACION DE CONTACTOS BLOQUEADOS
// Agrega los numeros que el bot NO debe responder
// Formato: codigo de pais + numero, sin + ni espacios
// Ejemplo: '521234567890' para Mexico
// ============================================

const contactosBloqueados = [
  'NUMERO_PAPA',     // Papa - reemplazar con numero real
  'NUMERO_MAMA',     // Mama - reemplazar con numero real  
  'NUMERO_NOVIO'     // Novio - reemplazar con numero real
];

// Extraer el numero del remitente
const mensajeData = $input.first().json.body?.data || $input.first().json.body || {};
const remitente = mensajeData.key?.remoteJid || mensajeData.remoteJid || '';
const numeroLimpio = remitente.replace('@s.whatsapp.net', '').replace('@g.us', '');

// Verificar si esta bloqueado
const estaBloqueado = contactosBloqueados.some(num => 
  numeroLimpio.includes(num) || num.includes(numeroLimpio)
);

// Extraer el mensaje de texto
const mensaje = mensajeData.message?.conversation || 
                mensajeData.message?.extendedTextMessage?.text ||
                mensajeData.message?.imageMessage?.caption ||
                mensajeData.message?.videoMessage?.caption ||
                '';

// Detectar si es un mensaje de estado/story
const esEstado = remitente === 'status@broadcast';

// Verificar que sea un mensaje entrante (no enviado por nosotros)
const esEntrante = !mensajeData.key?.fromMe;

return [{
  json: {
    remitente: numeroLimpio,
    remoteJid: remitente,
    mensaje: mensaje,
    estaBloqueado: estaBloqueado,
    esEstado: esEstado,
    esEntrante: esEntrante,
    tieneTexto: mensaje.length > 0,
    timestamp: new Date().toISOString(),
    nombreContacto: mensajeData.pushName || 'Desconocido'
  }
}];

// ============================================
// CONFIGURACION DEL BOT - EDITA AQUI
// ============================================

const config = {
  // DATOS DEL NEGOCIO
  nombreNegocio: 'Tu Comunidad',
  nombreAsistente: 'Asistente de [TU NOMBRE]',

  // PRODUCTOS - Modifica precios, nombres y descripciones
  productos: [
    {
      nombre: 'Mentoria Individual 1:1',
      precio: '$97 USD',
      descripcion: 'Sesion personalizada de 60 min para trabajar tu caso especifico',
      beneficios: 'Atencion personalizada, plan de accion, seguimiento 7 dias, materiales exclusivos'
    },
    {
      nombre: 'Mentoria Grupal',
      precio: '$47 USD',
      descripcion: 'Sesion grupal semanal con la comunidad',
      beneficios: 'Networking, sesiones en vivo semanales, comunidad privada, grabaciones'
    },
    {
      nombre: 'Comunidad Premium',
      precio: '$27 USD/mes',
      descripcion: 'Acceso mensual con contenido exclusivo',
      beneficios: 'Contenido semanal, grupo privado, descuentos en mentorias, recursos descargables'
    }
  ],

  // PROMOCION ACTIVA - Cambia a true cuando tengas promo
  promocionActiva: false,
  promocion: {
    nombre: '',
    descuento: '',
    codigo: '',
    fechaFin: '',
    mensaje: ''
  },

  // METODO DE PAGO
  metodoPago: 'Para realizar tu pago puedes hacerlo por transferencia o por el link que te comparto. Link: [TU_LINK]',

  // INSTRUCCIONES EXTRA - Agrega aqui lo que quieras
  instruccionesExtra: 'Sin instrucciones adicionales por ahora'
};

// Construir el prompt del sistema
const productosTexto = config.productos.map(p => 
  `- ${p.nombre} (${p.precio}): ${p.descripcion}. Beneficios: ${p.beneficios}`
).join('\n');

let promoTexto = '';
if (config.promocionActiva) {
  promoTexto = `\n\nPROMOCION ACTIVA: ${config.promocion.nombre} - ${config.promocion.descuento}. Codigo: ${config.promocion.codigo}. Valida hasta: ${config.promocion.fechaFin}. Mencionala de forma natural cuando sea relevante.`;
}

const systemPrompt = `Eres el asistente personal de ${config.nombreAsistente} en WhatsApp. Atiendes personas interesadas en mentorias y la comunidad.

PERSONALIDAD:
- Hablas como persona real, NUNCA como robot
- Tono amigable, profesional, cercano pero sin ser desesperado
- Mensajes CORTOS: maximo 3-4 oraciones
- Usas 1-2 emojis por mensaje, natural
- NUNCA dices que eres bot o IA. Si preguntan: "Soy parte del equipo"
- Escribes como en WhatsApp: natural, directo

TECNICAS DE VENTA:
1. ESPEJO EMOCIONAL: Antes de vender, conecta con lo que siente. Valida su emocion
2. PREGUNTAS ESTRATEGICAS: No bombardees info. Pregunta que necesitan
3. DOLOR > SOLUCION > ACCION: Refleja su dolor, presenta solucion, da paso claro
4. URGENCIA REAL: Solo si hay promo o disponibilidad limitada real
5. CIERRE SUAVE: Guia, no presiones. "Te gustaria que te cuente como funciona?"
6. OBJECIONES:
   - "Es caro" > Habla del valor, compara con costo de no actuar
   - "Lo pienso" > "Claro, tomate tu tiempo. Solo que [beneficio urgente]"
   - "No tengo tiempo" > "Esta disenado para personas ocupadas"
   - "No se si es para mi" > Pregunta mas para personalizar

PRODUCTOS:
${productosTexto}
${promoTexto}

METODO DE PAGO:
${config.metodoPago}

REGLAS CRITICAS:
- NUNCA inventes info que no esta aqui
- NUNCA prometas cosas no listadas
- Si no sabes: "Dejame confirmarlo y te aviso"
- Si piden hablar con [nombre]: "Claro, le paso tu mensaje"
- Si hay queja: NO vendas, escucha y ofrece solucion
- Responde SOLO al mensaje actual
- No mandes mensajes largos

${config.instruccionesExtra}

FLUJO: Saludo breve > Pregunta > Escucha > Solucion > Dudas > Cierre suave > Pago > Confirma`;

const mensajeUsuario = $input.first().json.mensaje;
const nombreContacto = $input.first().json.nombreContacto;

return [{
  json: {
    systemPrompt: systemPrompt,
    mensajeUsuario: mensajeUsuario,
    nombreContacto: nombreContacto,
    remitente: $input.first().json.remitente,
    remoteJid: $input.first().json.remoteJid,
    timestamp: $input.first().json.timestamp
  }
}];

const response = $input.first().json;

// Extraer la respuesta de Claude
let respuestaBot = '';

if (response.content && response.content.length > 0) {
  respuestaBot = response.content[0].text;
} else if (response.error) {
  respuestaBot = 'Hola! Dame un momento, ya te atiendo personalmente';
}

// Limpiar la respuesta
respuestaBot = respuestaBot.trim();

// Si la respuesta es muy larga, cortarla
if (respuestaBot.length > 500) {
  const punto = respuestaBot.lastIndexOf('.', 500);
  if (punto > 200) {
    respuestaBot = respuestaBot.substring(0, punto + 1);
  }
}

return [{
  json: {
    respuesta: respuestaBot,
    remitente: $('Preparar Prompt de Ventas').first().json.remitente,
    remoteJid: $('Preparar Prompt de Ventas').first().json.remoteJid
  }
}];

// Delay aleatorio para que no parezca bot (1-4 segundos)
const delay = Math.floor(Math.random() * 3000) + 1000;
await new Promise(resolve => setTimeout(resolve, delay));

return $input.all();
